   349      DEBUG_MSG_LEVEL (SANITIZE, p, this->debug_depth+1, 0,
   350         "may_edit(%u) [%p..%p] (%d bytes) in [%p..%p] -> %s",
   351         this->edit_count,
   352         p, p + len, len,
   353         this->start, this->end,
   354         this->writable ? "GRANTED" : "DENIED");
   355
   356      return this->writable;
   357    }
